/**
 * Asynchronous work started through v3, and automatic follow-up work (auto-dub, on-screen auto-start, the stages of a localization run) on projects created through v3. Started by 202 responses (`Location: /v3/jobs/{id}`); wait with getJob `wait_seconds`. Finished jobs can be read for 90 days, then answer 404 `job_not_found`. Work started in the web app or API v2 has no job.
 */
export type Job = {
    /**
     * Always `job`.
     */
    object: 'job';
    /**
     * Job id.
     */
    id: string;
    /**
     * Workspace that owns the job (and whose owner pays).
     */
    workspace_id: string;
    type: JobType;
    status: JobStatus;
    /**
     * 0-100; null when the type has no honest progress.
     */
    progress: number | null;
    /**
     * Per-type stage; for a `localization` job, the running stage's.
     */
    stage: JobStage | null;
    /**
     * Queue position (1 = next).
     */
    queue_position: number | null;
    /**
     * Estimated completion from the queue position and the type's typical duration (on-screen: the runner's ETA); null when terminal or unknown. An estimate, not a deadline.
     */
    estimated_finish_at: string | null;
    /**
     * True once the job runs past its type's overdue threshold: Rask is alerted. Keep waiting or check back later; do not start the same work again.
     */
    overdue: boolean;
    /**
     * Project.
     */
    project_id: string | null;
    /**
     * Media.
     */
    media_id: string | null;
    /**
     * The job that started this system job: the project_processing job of an auto-dub, the dub whose merge started an on-screen auto-start, the `localization` job of a stage, the project_processing job of a `localization` block, or the failed run a resumed `localization` job continues.
     */
    parent_job_id: string | null;
    channel: JobChannel;
    params: JobParams;
    /**
     * Live per-type state.
     */
    details: JobDetails | null;
    /**
     * The stages of a `localization` job in run order; null for other types.
     */
    stages: Array<LocalizationStage> | null;
    /**
     * Quoted at creation; `charged` turns true once the charge is committed. A `localization` job has no charge of its own: `minutes` is the sum of its stages charged and not refunded so far, `charged` is true once any stage is charged, `refunded` is true only when every charged stage was refunded, `refunded_at` is the latest refund. `stages[].cost` holds each stage; the quote is `params.expected_cost_minutes`.
     */
    cost: Cost | null;
    /**
     * Set when succeeded; a failed `segment_generation` job may also list clips already voiced.
     */
    result: JobResult | null;
    /**
     * Set when failed; on a canceled job only for the cancellation reason `project_deleted` (the project was deleted while the job ran; its work is discarded, refunded only for on-screen); `instance` is `/v3/jobs/{id}`, `detail` is generic. Each code's `status`, `retry`, `recommendation` and `hint` are in `components.x-rask-job-errors`. Codes by type: media_import `source_download_failed`, `unsupported_media_type`, `media_corrupt`, `media_processing_failed`, `media_too_large` (a voice sample above its limit); project_processing `media_processing_failed`, `source_unavailable`, `no_audio_track`, `transcription_failed`, `no_speech_detected`, `audio_separation_failed`, `speaker_detection_failed`, `translation_failed`, `subtitle_import_rolled_back`, `project_processing_timeout`, `internal_error`; translation `translation_failed`, `translation_dispatch_failed`, `translation_timeout`; segment_generation (`cause_code`) `segment_generation_failed`, `segment_generation_timeout`; localization `localization_stage_failed`, `localization_stage_skipped` (`failed_stage`, `cause_code`); dub (`cause_code`) `dub_voiceover_failed`, `dub_merge_failed`, `dub_failed`, `dub_timeout`; lipsync `lipsync_failed`, `face_check_failed`, `no_face_detected`, `lipsync_rejected` (`cause_code`), `lipsync_timeout`; onscreen `onscreen_queue_timeout`, `onscreen_runner_lost`, `onscreen_runner_failed`, `onscreen_provider_unavailable`, `onscreen_finalize_timeout`, `onscreen_invalid_result`, `onscreen_publish_failed`, `onscreen_source_unavailable`, `onscreen_charge_failed`; voice_clone `voice_clone_failed`, `voice_clone_timeout`; export `export_failed`; file_restore `restore_failed`. A failed job refunds its minutes (`onscreen_charge_failed` never charged). A failed `localization` job refunds only the failed stage, by its type's rule: succeeded stages stay charged, and skipped or unreached stages were never charged. A failed `project_processing` job refunds its project credit when a stage from transcription to translation failed, when it timed out and when a copy failed, but not for `media_processing_failed`, `source_unavailable`, `no_audio_track` or the `internal_error` of a new project.
     */
    error: Problem | null;
    /**
     * Creation time.
     */
    created_at: string;
    /**
     * Start time.
     */
    started_at: string | null;
    /**
     * End time.
     */
    finished_at: string | null;
    links: JobLinks;
};

/**
 * Live per-type state: a union on `type`. Null for types without live details.
 */
export type JobDetails = OnscreenJobDetails;

/**
 * Path-absolute API links.
 */
export type JobLinks = {
    /**
     * This job.
     */
    self: string;
    /**
     * The project.
     */
    project: string | null;
    /**
     * The project's outputs.
     */
    outputs: string | null;
    /**
     * The media.
     */
    media: string | null;
};

/**
 * A page of `Job` (the list envelope shared by every list).
 */
export type JobList = {
    /**
     * Always `list`.
     */
    object: 'list';
    /**
     * Items of this page.
     */
    data: Array<Job>;
    /**
     * Pass as `cursor` for the next page; null on the last page.
     */
    next_cursor: string | null;
    /**
     * More items exist (a page may hold fewer than `limit` items while has_more is true).
     */
    has_more: boolean;
};

/**
 * A non-blocking notice in a job result.
 */
export type JobNotice = {
    code: JobNoticeCode;
    /**
     * Explanation; never user text.
     */
    detail: string;
    /**
     * speaker_voice_unused, speaker_voice_not_applied: the speaker labels concerned; otherwise null.
     */
    speaker_labels: Array<string> | null;
};

/**
 * Normalized request echo: a union on `type` (= Job.type).
 */
export type JobParams = ({
    type: 'media_import';
} & MediaImportJobParams) | ({
    type: 'project_processing';
} & ProjectProcessingJobParams) | ({
    type: 'translation';
} & TranslationJobParams) | ({
    type: 'segment_generation';
} & SegmentGenerationJobParams) | ({
    type: 'dub';
} & DubJobParams) | ({
    type: 'lipsync';
} & LipsyncJobParams) | ({
    type: 'onscreen';
} & OnscreenJobParams) | ({
    type: 'localization';
} & LocalizationJobParams) | ({
    type: 'voice_clone';
} & VoiceCloneJobParams) | ({
    type: 'export';
} & ExportJobParams) | ({
    type: 'file_restore';
} & FileRestoreJobParams);

/**
 * Per-type result: a union on `type`. Download links inside are minted at read time and are null in webhook payloads.
 */
export type JobResult = ({
    type: 'media_import';
} & MediaImportJobResult) | ({
    type: 'project_processing';
} & ProjectProcessingJobResult) | ({
    type: 'translation';
} & TranslationJobResult) | ({
    type: 'segment_generation';
} & SegmentGenerationJobResult) | ({
    type: 'dub';
} & DubJobResult) | ({
    type: 'lipsync';
} & LipsyncJobResult) | ({
    type: 'onscreen';
} & OnscreenJobResult) | ({
    type: 'localization';
} & LocalizationJobResult) | ({
    type: 'voice_clone';
} & VoiceCloneJobResult) | ({
    type: 'export';
} & ExportJobResult) | ({
    type: 'file_restore';
} & FileRestoreJobResult);

