/**
 * RFC 9457 problem details (`application/problem+json`), used for every 4xx/5xx response and for `Job.error`. Branch on `code`; follow `hint`; act as `recommendation` says; retry as `retry` says. An extension member has one type across all codes and never reuses an RFC 9457 or Problem member name (hence `job_type`, and `active_job_count` for a count beside `active_jobs` for a list). Extension members appear only with the codes that define them (see each property). The problem registry and one documentation page per code live at https://docs.api.rask.ai/errors.
 */
export type Problem = {
    /**
     * `https://docs.api.rask.ai/errors/{code}`: one documentation page per code.
     */
    type: string;
    /**
     * Short summary of the problem type.
     */
    title: string;
    /**
     * HTTP status (for a job's error: the status the same failure would have synchronously).
     */
    status: number;
    /**
     * Explanation of this occurrence. May name ids, never user text.
     */
    detail: string;
    /**
     * `urn:uuid:<request_id>` (also in `X-Request-Id`); for a job's error, `/v3/jobs/{job_id}`.
     */
    instance: string;
    /**
     * Stable snake_case code from the problem registry. Branch on this value, never on text.
     */
    code: string;
    /**
     * True when a retry can succeed; `retry` says how.
     */
    retryable: boolean;
    /**
     * How to retry: `same_key` for request problems that may succeed later, `new_key` for job errors worth a new attempt, `none` otherwise. `retryable` is true exactly when this is not `none`.
     */
    retry: ProblemRetry;
    /**
     * What has to happen before a retry can succeed; set per code, and per `cause_code` for dub and generation failures (`components.x-rask-job-errors`). `cause_code: unknown`: `retry_later`, or `contact_support` when the same project's previous job of that type also failed with `unknown`.
     */
    recommendation: ProblemRecommendation;
    /**
     * One imperative sentence naming the next call or field (<= 160 characters).
     */
    hint: string | null;
    /**
     * Failing fields; empty when the problem is not about fields.
     */
    errors: Array<ProblemFieldError>;
    /**
     * insufficient_balance, token_spend_limit_exceeded: the pool concerned.
     */
    credit_type?: CreditType;
    /**
     * insufficient_balance, token_spend_limit_exceeded: minutes the request needs.
     */
    required_minutes?: number;
    /**
     * insufficient_balance: minutes available in the pool.
     */
    balance_minutes?: number;
    /**
     * insufficient_balance (projects pool), token_spend_limit_exceeded (projects cap): project credits needed.
     */
    required_projects?: number;
    /**
     * insufficient_balance (projects pool): project credits available.
     */
    balance_projects?: number;
    /**
     * cost_changed: the cap the request sent.
     */
    expected_cost_minutes?: number;
    /**
     * cost_changed: the current price.
     */
    current_cost_minutes?: number;
    /**
     * precondition_failed: the resource's current ETag.
     */
    current_etag?: string;
    /**
     * insufficient_scope: every scope the request needs, including those of `x-rask-operation.conditional`.
     */
    required_scopes?: Array<Scope>;
    /**
     * insufficient_scope: the key's scopes.
     */
    granted_scopes?: Array<Scope>;
    feature?: EntitlementFeature;
    /**
     * workspace_access_suspended, source_url_not_allowed, webhook_url_not_allowed, instant_clone_not_available, job_not_resumable, localization_combination_not_supported: machine-readable reason. workspace_access_suspended: `subscription_inactive` (the owner's subscription is not active), `space_limit_exceeded` (the owner has more workspaces than the plan allows), `seat_limit_exceeded` (the key's user is beyond the plan's seats). job_not_resumable: `not_failed_localization`, `already_resumed`, `project_deleted`, `stage_result_gone`. localization_combination_not_supported: `nothing_ordered`, `audio_project`, `plan_trims_lipsync`.
     */
    reason?: string;
    /**
     * limit_reached, voice_clone_limit_reached, rate_limited, too_many_waiters, too_many_concurrent_jobs, translation_batch_too_large: the limit.
     */
    limit?: number;
    /**
     * voice_clone_limit_reached: clones counted against the quota.
     */
    used?: number;
    /**
     * token_spend_limit_exceeded (minutes cap): the key's monthly cap on the minutes pool.
     */
    limit_minutes?: number;
    /**
     * token_spend_limit_exceeded (minutes cap): minutes spent this month by the key, with pending deferred spends.
     */
    spent_minutes?: number;
    /**
     * token_spend_limit_exceeded (projects cap): the key's monthly cap on project credits.
     */
    limit_projects?: number;
    /**
     * token_spend_limit_exceeded (projects cap): project credits spent this month by the key, with pending deferred spends.
     */
    spent_projects?: number;
    /**
     * token_spend_limit_exceeded: start of the next UTC month.
     */
    resets_at?: string;
    /**
     * rate_limited, too_many_waiters, too_many_concurrent_jobs: the exceeded policy or quota. rate_limited: credential-minute, account-minute, spend-minute, upload-hour, auth-fail-ip, translation-hour, clone-create-day, voice-settings-hour, upload-open, upload-bytes-day; too_many_waiters: long-poll (per key and per payer); too_many_concurrent_jobs: payer-concurrency, global-concurrency.
     */
    policy?: string;
    /**
     * rate_limited: the policy window.
     */
    window_seconds?: number;
    /**
     * too_many_concurrent_jobs: active API and MCP jobs of this type (the payer's, or all of Rask's for global-concurrency).
     */
    active_job_count?: number;
    /**
     * project_busy: the project's active spending jobs.
     */
    active_jobs?: Array<ActiveJobRef>;
    /**
     * transcript_busy: the active jobs that block a whole-transcript request; absent when concurrent writes kept conflicting.
     */
    active_job_ids?: Array<string>;
    /**
     * segment_busy: the busy segments.
     */
    segment_ids?: Array<string>;
    /**
     * The blocking job: dub_in_progress, lipsync_in_progress, onscreen_in_progress, project_not_ready and transcript_busy (null when the blocking work has no v3 job, e.g. it was started in the web app; `job_type` still names it), export_in_progress, restore_in_progress, media_in_use, subtitle_import_in_progress. job_not_resumable: the job that already continues this run, when there is one.
     */
    job_id?: string | null;
    /**
     * Type of `job_id` (single-flight conflicts), of the job that cannot be canceled or resumed (job_not_cancelable, job_not_resumable), or whose concurrency limit was reached (too_many_concurrent_jobs).
     */
    job_type?: JobType;
    /**
     * media_not_ready: the media_import job to wait for.
     */
    import_job_id?: string;
    /**
     * onscreen_video_too_long: the plan's limit (`onscreen_max_video_seconds`).
     */
    max_seconds?: number;
    /**
     * token_expired, upload_expired: when it expired.
     */
    expired_at?: string;
    /**
     * token_revoked: why the key was revoked.
     */
    revoked_reason?: string;
    /**
     * token_wrong_environment: the key's environment (`live` or `test`).
     */
    token_env?: string;
    /**
     * token_wrong_environment: this server's environment.
     */
    server_env?: string;
    /**
     * token_in_query: the query parameter that carried a credential.
     */
    parameter?: string;
    /**
     * media_too_large: the limit in bytes (the plan's upload limit, or a voice-sample limit: 11000000 for audio and stored samples, 500000000 for video).
     */
    max_upload_bytes?: number;
    /**
     * media_too_large: the file size in bytes.
     */
    size_bytes?: number;
    /**
     * media_too_long: the plan's limit.
     */
    max_source_duration_seconds?: number;
    /**
     * media_too_long: the media duration.
     */
    duration_seconds?: number;
    /**
     * upload_size_mismatch: size_bytes of the upload.
     */
    declared_size_bytes?: number;
    /**
     * upload_size_mismatch: size of the stored object.
     */
    actual_size_bytes?: number;
    /**
     * folder_not_empty: live projects in the folder.
     */
    project_count?: number;
    /**
     * unsupported_media_type: the rejected content type.
     */
    content_type?: string;
    /**
     * Job errors. lipsync_rejected: the code that rejected the automatic start. dub_voiceover_failed, dub_merge_failed, dub_failed, dub_timeout, segment_generation_failed, segment_generation_timeout (always `unknown` on a timeout): the failure class, one of `segment_changed`, `insufficient_speech`, `voice_configuration`, `missing_translation`, `tts_provider_failed`, `merge_failed`, `unknown` (the default when the class cannot be told). localization_stage_failed, localization_stage_skipped: the code of the stage's own error; `localization_combination_not_supported` when a plan change during the run trimmed the lip-sync, so on-screen was skipped.
     */
    cause_code?: string;
    /**
     * localization_stage_failed, localization_stage_skipped (job error): the stage that ended the run.
     */
    failed_stage?: LocalizationStageName;
    [key: string]: unknown;
};

/**
 * One failing field of a request.
 */
export type ProblemFieldError = {
    /**
     * JSON Pointer into the request body (`/operations/3/start_seconds`), or a `query:`, `header:` or `path:` prefixed parameter name.
     */
    pointer: string;
    /**
     * Stable snake_case code of this field error. Segment writes: `invalid_time`, `start_not_before_end`, `beyond_media_duration`, `segment_too_short`, `segment_too_long`, `invalid_speaker_id`, `too_many_speakers`, `text_too_long`, `invalid_text`, `transcript_too_large`, `split_point_outside_segment`, `segments_not_adjacent`, `too_many_segments`, `segment_targeted_twice`, `unknown_segment`, `variant_not_found`; spending requests: `expected_cost_required`; uploads: `part_missing`; generic schema failures use JSON Schema keyword names (`required`, `maxLength`, ...).
     */
    code: string;
    /**
     * Human-readable explanation. Never contains user text.
     */
    detail: string;
};

/**
 * Why processing failed.
 */
export type ProcessingFailure = {
    code: ProcessingFailureCode;
    /**
     * Stage that failed.
     */
    stage: ProjectStage | null;
    /**
     * True when the editor still works and dubbing again may succeed.
     */
    recoverable: boolean;
    /**
     * Generic explanation.
     */
    message: string;
};

/**
 * Server-derived processing state of a project.
 */
export type ProcessingState = {
    phase: ProcessingPhase;
    /**
     * True when nothing runs (with done or awaiting_user: review, edit or dub).
     */
    terminal: boolean;
    /**
     * Pipeline run number.
     */
    run_id: number;
    /**
     * Status sequence number; increases with every status.
     */
    seq: number;
    /**
     * Current stage.
     */
    stage: ProjectStage | null;
    /**
     * Set when phase is failed.
     */
    failure: ProcessingFailure | null;
};

/**
 * A localization project: one media item localized into one target language.
 */
export type Project = {
    /**
     * Always `project`.
     */
    object: 'project';
    /**
     * Project id.
     */
    id: string;
    /**
     * Project name.
     */
    name: string;
    /**
     * Workspace id.
     */
    workspace_id: string;
    /**
     * Creation time.
     */
    created_at: string;
    created_by: UserRef;
    /**
     * Folder; null at the root.
     */
    folder: FolderRef | null;
    /**
     * Media the project was created from.
     */
    source_media_id: string | null;
    source: ProjectSource;
    /**
     * Media kind.
     */
    media_kind: MediaKind | null;
    /**
     * Source language (detected after transcription when auto).
     */
    source_language: string | null;
    /**
     * Target language.
     */
    target_language: string | null;
    /**
     * Uses the free dubbing variant.
     */
    free_dubbing: boolean;
    /**
     * The model named in the create request; null when the request named none or the project was not created through v3.
     */
    requested_dubbing_model: DubbingModel | null;
    /**
     * Effective dubbing model: `v2` when the project runs meaning-first (settled at creation by the request, the language and whether Rask has meaning-first on for paid projects; on a trial, by the trial rule), its voices can use it (`Voice.meaning_first_compatible`) and it is not a free dubbing variant; otherwise `v1`.
     */
    dubbing_model: DubbingModel | null;
    /**
     * Why `dubbing_model` differs from the request, or from the default `v2` when the request named none; null when it does not differ.
     */
    dubbing_model_override_reason: DubbingModelOverrideReason | null;
    /**
     * Engine of the last finished voiceover; null before the first one.
     */
    last_dub_engine: DubEngine | null;
    /**
     * Speakers.
     */
    num_speakers: number | null;
    /**
     * Processed duration.
     */
    duration_seconds: number | null;
    /**
     * Original duration.
     */
    source_duration_seconds: number | null;
    /**
     * The processed duration is shorter than the original.
     */
    trimmed: boolean;
    /**
     * Created on a trial: watermarked, not redubbable.
     */
    trial: boolean;
    /**
     * Attached glossary.
     */
    glossary: ProjectGlossary | null;
    /**
     * Translation instructions.
     */
    translation_instructions: string | null;
    subtitles_imported: SubtitlesImported;
    auto_dub: ProjectAutoDub;
    onscreen_auto_start: ProjectOnscreenAutoStart;
    processing_state: ProcessingState;
    /**
     * Raw last pipeline status (37 values). Informational only: use processing_state.
     */
    pipeline_status: string;
    /**
     * Time of the last status.
     */
    pipeline_status_at: string | null;
    /**
     * A dubbed video exists.
     */
    has_dubbed_output: boolean;
    /**
     * Archived files are being restored.
     */
    files_restoring: boolean;
    /**
     * Non-terminal v3 jobs of the project (work started in the web app has none; see `processing_state`).
     */
    active_jobs: Array<ProjectActiveJob>;
    /**
     * Downloadable outputs, as listProjectOutputs reports them (`dub_payment_required` included); null in lists.
     */
    outputs: Array<Output> | null;
    /**
     * Client metadata (string map); never sent in webhooks.
     */
    metadata: {
        [key: string]: string;
    };
};

/**
 * A non-terminal v3 job of the project.
 */
export type ProjectActiveJob = {
    /**
     * Job id.
     */
    id: string;
    type: JobType;
    status: JobStatus;
};

/**
 * Auto-dub settings and state. With a `localization` block, `state` is `dispatched` once the run starts and `skipped_reason` stays null; read the run's job.
 */
