    /**
     * Current period start.
     */
    current_period_start: string | null;
    /**
     * Current period end.
     */
    current_period_end: string | null;
    /**
     * Cancels at period end.
     */
    cancel_at_period_end: boolean;
    /**
     * Payment collection is paused.
     */
    paused: boolean;
    /**
     * A scheduled downgrade or change.
     */
